import math

# Constraints: 1 <= x < y, gcd(x, y) = 1, x^2 + y^2 < 300

max_y = int(math.sqrt(300 - 1)) # y <= 17

coprime_pairs_sums = []

for y in range(2, max_y + 1):
    for x in range(1, y):
        if math.gcd(x, y) == 1:
            m = x**2 + y**2
            if m < 300:
                coprime_pairs_sums.append(m)

# Sort and find the 20th smallest
coprime_pairs_sums.sort()

if len(coprime_pairs_sums) >= 20:
    result = coprime_pairs_sums[19] # 20th smallest (0-indexed)
    print(f"Total coprime pairs found: {len(coprime_pairs_sums)}")
    print(f"The 20th smallest sum is: {result}")
else:
    print(f"Not enough coprime pairs found. Total: {len(coprime_pairs_sums)}")

import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

good_numbers = set()
limit_m = 10000  # Search up to 10000 to ensure 20th term is found

# Iterate over g (the GCD)
g = 2
while True:
    # Iterate over x' and y' (coprime, x' < y')
    # We limit the search such that g^2 * ((x')^2 + (y')^2) does not exceed the limit_m

    # Smallest sum of squares (1^2 + 2^2) = 5. So g^2 * 5 < limit_m
    max_g_sq = limit_m // 5
    if g * g > max_g_sq:
        break

    for x_prime in range(1, 100):
        for y_prime in range(x_prime + 1, 100):
            if gcd(x_prime, y_prime) == 1:
                m = (g * g) * (x_prime**2 + y_prime**2)

                if m > limit_m:
                    # Optimization: Since y' is increasing, we can break the inner loop
                    break

                if m > 0:
                    good_numbers.add(m)

    g += 1

# Sort and check the 20th element
sorted_good_numbers = sorted(list(good_numbers))

if len(sorted_good_numbers) >= 20:
    print(f"Found {len(sorted_good_numbers)} unique good numbers under the limit.")
    print(f"The 20th smallest good number is: {sorted_good_numbers[19]}")
else:
    print(f"Only found {len(sorted_good_numbers)} unique good numbers under the limit.")
